type SearchVectorStoreParams struct {
	VectorStoreId  string
	Query          any
	RewriteQuery   *bool
	MaxNumResults  *int64
	Filters        *VectorStoreSearchRequestFilters
	RankingOptions *VectorStoreSearchRequestRankingOptions
}

// SearchVectorStore searches a vector store for relevant file chunks using one or more queries and optional file-attribute filters. Set `max_num_results` to control the result count and `ranking_options` to configure ranking; use `next_page` to continue when more results are available.
//
// Search a vector store for relevant chunks based on a query and file attributes filter.
//
// Parameters:
//
//	vectorStoreId: The ID of the vector store to search.
//	query: A query string for a search
//	rewriteQuery: Whether to rewrite the natural language query for vector
//	search.
//	maxNumResults: The maximum number of results to return. This number should
//	be between 1 and 50 inclusive.
//	filters: A filter to apply based on file attributes.
//	rankingOptions: Ranking options for search.
func SearchVectorStore(ctx context.Context, clientConfig ClientConfig, params SearchVectorStoreParams, opts ...RequestOption) (*VectorStoreSearchResultsPage, error) {
	vectorStoreId := params.VectorStoreId
	query := params.Query
	rewriteQuery := params.RewriteQuery
	maxNumResults := params.MaxNumResults
	filters := params.Filters
	rankingOptions := params.RankingOptions

	if maxNumResults != nil {
		if err := ValidateRange("max_num_results", *maxNumResults, RangeOpts{Min: Ptr[float64](1), Max: Ptr[float64](50)}); err != nil {
			return nil, err
		}
	}

	resp, err := DoCfg[VectorStoreSearchResultsPage](ctx, &clientConfig, "POST", fmt.Sprintf("/vector_stores/%s/search", EncodePathSegment(vectorStoreId)), &RequestOpts{
		Body: map[string]any{
			"query":           query,
			"rewrite_query":   rewriteQuery,
			"max_num_results": maxNumResults,
			"filters":         filters,
			"ranking_options": rankingOptions,
		},
		OperationID: "SearchVectorStore",
		Errors:      ErrorDecoders{"400": decodeErrorData[ErrorResponse], "404": decodeErrorData[ErrorResponse], "429": decodeErrorData[ErrorResponse]},
		Options:     opts,
	})
	if err != nil {
		return nil, err
	}
	return &resp.Data, nil
}
